<script lang="ts">import { createApiClient } from '$lib/api/index'; let { data } = $props(); let downloading = $state<string | null>(null); async function download(item:any){downloading=item.studentId;try{const b=await createApiClient(data.token).getBlob(`/psychological-reports/${item.assignmentId}/${item.studentId}/download`);const u=URL.createObjectURL(b);const a=document.createElement('a');a.href=u;a.download='laporan-psikologis.pdf';a.click();URL.revokeObjectURL(u)}finally{downloading=null}}</script>
<svelte:head><title>Laporan Psikologis</title></svelte:head><div class="wrap"><h2>Laporan Psikologis</h2><p>Akses lintas sekolah untuk psikolog.</p>{#each data.reports.items as item}<article><div><strong>{item.studentName}</strong><span>{item.schoolName}</span></div><a href={`/psikolog-reports/${item.assignmentId}/${item.studentId}`}>Buka</a><button onclick={()=>download(item)}>{downloading===item.studentId?'Menyiapkan…':'PDF'}</button></article>{/each}</div><style>.wrap{display:grid;gap:1rem}.wrap p,span{color:var(--lp-ink-2)}article{display:flex;align-items:center;gap:1rem;border:1px solid var(--lp-rule);border-radius:.75rem;padding:1rem}article div{margin-right:auto;display:grid}button{border:0;border-radius:.5rem;padding:.45rem .7rem;background:var(--lp-accent-deep);color:white}</style>
